#include <vector>
#include <unordered_map>
#include <queue>
#include <algorithm>
#include <functional>

#define INF 0x3f3f3f3f

std::vector<int> dijkstra(int n, const std::vector<std::tuple<int, int, std::vector<int>>>& adjacency_list) {
    std::vector<std::vector<std::pair<int, int>>> adj(n + 1);
    for (auto& [u, k, neighbours] : adjacency_list) {
        for (int v : neighbours) {
            adj[u].emplace_back(v, k);
        }
    }
    std::vector<int> dist(n + 1, INF);
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<>> pq;
    pq.push({0, 1});
    dist[1] = 0;
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;
        for (auto& [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;
    std::vector<std::tuple<int, int, std::vector<int>>> adjacency_list(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> std::get<0>(adjacency_list[i]);
        std::cin >> std::get<1>(adjacency_list[i]);
        std::get<2>(adjacency_list[i]).resize(std::get<1>(adjacency_list[i]));
        for (auto& v : std::get<2>(adjacency_list[i])) {
            std::cin >> v;
        }
    }
    std::vector<int> dist = dijkstra(n, adjacency_list);
    for (int i = 1; i <= n; ++i) {
        std::cout << (dist[i] == INF? -1 : dist[i]) << (i < n?'' : '\n');
    }
    return 0;
}
